import { fill } from "./fill";
import type { TextLocale } from "./checkboxes";

/**
 * Fixed prelude spoken to the adult who answers (docs/legal/textos/03, section B). NOT generated by a model.
 * Exact texts, version legal-v1.2 (D13). Santa is implemented; other characters are added as new entries
 * (Reyes, Rex, Perez: section B2/B3) without touching the engine.
 */
export interface PreludeTexts {
  /** Version id stored with every call, e.g. 03-SANTA-es-419-legal-v1.2. */
  id: string;
  /** Step 3: main notice. Max 35 s. */
  main: string;
  /** Step 4: repeat, only the last sentence. */
  repeat: string;
  /** Step 5, key 1: hand-off to the child. */
  handoff: string;
  /** Step 7: repeated once after 30 s without the second key. */
  handoffRepeat: string;
  /** Step 5, key 2. */
  optout: string;
  /** Step 4, no key after the repeat. */
  noResponse: string;
  /** Step 6: any other key. */
  pressOne: string;
  /** First line of the character after the second key 1. */
  firstLine: string;
  /** Fixed closing phrase (B4 / D-02) if the model runs out of time. */
  closing: string;
}

/** Version of the text package. Santa text ids carry the "-legal-v1.2" suffix (03 section H). */
export const PRELUDE_VERSION = "legal-v1.2";

